import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Button, Form, FormGroup, Label, Input } from 'reactstrap';

const ContractModal = ({ isOpen, toggle, email, toId, initialProposal, refreshProposals }) => {
    const [formData, setFormData] = useState({
        fromId: email,
        toId: toId,
        goodName: '',
        goodDetail: '',
        goodRequire: '',
        term: '',
        payWay: '',
        pay: '',
        photoUrl: null,
    });

    useEffect(() => {
        if (initialProposal) {
            setFormData({
                fromId: initialProposal.fromId,
                toId: initialProposal.toId,
                goodName: initialProposal.goodName,
                goodDetail: initialProposal.goodDetail,
                goodRequire: initialProposal.goodRequire,
                term: initialProposal.term,
                payWay: initialProposal.payWay,
                pay: initialProposal.pay,
                photoUrl: initialProposal.photoUrl,
            });
        }
    }, [initialProposal]);

    const handleChange = (e) => {
        const { name, value, files } = e.target;
        if (files) {
            setFormData((prevData) => ({
                ...prevData,
                [name]: files[0],
            }));
        } else {
            setFormData((prevData) => ({
                ...prevData,
                [name]: value,
            }));
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        const url = initialProposal
            ? `http://localhost:8080/api/sendProposal/${initialProposal.id}`
            : 'http://localhost:8080/api/sendProposal';
        const method = initialProposal ? 'PUT' : 'POST';

        const formDataToSend = new FormData();
        formDataToSend.append('fromId', formData.fromId);
        formDataToSend.append('toId', formData.toId);
        if (formData.photoUrl instanceof File) {
            formDataToSend.append('photoUrl', formData.photoUrl);
        }
        formDataToSend.append('goodName', formData.goodName);
        formDataToSend.append('goodDetail', formData.goodDetail);
        formDataToSend.append('goodRequire', formData.goodRequire);
        formDataToSend.append('term', formData.term);
        formDataToSend.append('payWay', formData.payWay);
        formDataToSend.append('pay', formData.pay);

        try {
            const response = await fetch(url, {
                method: method,
                body: formDataToSend,
            });
            const data = await response.json();
            console.log('Proposal saved:', data);
            toggle();
            refreshProposals();
        } catch (error) {
            console.error('Error:', error);
        }
    };

    return (
        <Modal isOpen={isOpen} toggle={toggle}>
            <ModalHeader toggle={toggle}>{initialProposal ? '제안서 수정' : '제안서 추가'}</ModalHeader>
            <ModalBody>
                <Form onSubmit={handleSubmit}>
                    <FormGroup>
                        <Label for="goodName">상품명</Label>
                        <Input
                            type="text"
                            name="goodName"
                            id="goodName"
                            value={formData.goodName}
                            onChange={handleChange}
                        />
                    </FormGroup>
                    <FormGroup>
                        <Label for="goodDetail">상세 설명</Label>
                        <Input
                            type="text"
                            name="goodDetail"
                            id="goodDetail"
                            value={formData.goodDetail}
                            onChange={handleChange}
                        />
                    </FormGroup>
                    <FormGroup>
                        <Label for="goodRequire">요구사항</Label>
                        <Input
                            type="text"
                            name="goodRequire"
                            id="goodRequire"
                            value={formData.goodRequire}
                            onChange={handleChange}
                        />
                    </FormGroup>
                    <FormGroup>
                        <Label for="term">기간</Label>
                        <Input type="text" name="term" id="term" value={formData.term} onChange={handleChange} />
                    </FormGroup>
                    <FormGroup>
                        <Label for="payWay">결제 방식</Label>
                        <Input type="text" name="payWay" id="payWay" value={formData.payWay} onChange={handleChange} />
                    </FormGroup>
                    <FormGroup>
                        <Label for="pay">금액</Label>
                        <Input type="number" name="pay" id="pay" value={formData.pay} onChange={handleChange} />
                    </FormGroup>
                    <FormGroup>
                        <Label for="photoUrl">사진</Label>
                        <Input type="file" name="photoUrl" id="photoUrl" onChange={handleChange} />
                        {formData.photoUrl && !(formData.photoUrl instanceof File) && (
                            <div>
                                <img
                                    src={`http://localhost:8080/uploads/${formData.photoUrl}`}
                                    alt="Proposal"
                                    style={{ maxWidth: '100%', marginTop: '10px' }}
                                />
                            </div>
                        )}
                    </FormGroup>
                </Form>
            </ModalBody>
            <ModalFooter>
                <Button type="submit" color="primary">
                    {initialProposal ? '수정 완료' : '추가하기'}
                </Button>
                <Button color="secondary" onClick={toggle}>
                    닫기
                </Button>
            </ModalFooter>
        </Modal>
    );
};

export default ContractModal;
